+TEST_CASE("[UnorderedHashMap] Overwrite element") {
+	UnorderedHashMap<int, int> map;
+	map.insert(42, 84);
+	map.insert(42, 1234);
+
+	CHECK(map[42] == 1234);
+}
+
+TEST_CASE("[UnorderedHashMap] Erase via element") {
+	UnorderedHashMap<int, int> map;
+	UnorderedHashMap<int, int>::Iterator e = map.insert(42, 84);
+	map.remove(e);
+	CHECK(!map.has(42));
+	CHECK(!map.find(42));
+}
+
+TEST_CASE("[UnorderedHashMap] Erase via key") {
+	UnorderedHashMap<int, int> map;
